13	@Repository
14	public class BatchRepository {
15	
16	    /**
17	     * batch 表行记录；id 同时作为同批次事件的提交顺序依据。
18	     */
19	    public record BatchRow(long id, String batchKey, String productCode, String batchNo,
20	                           String producedAt, String status, String createdAt) {
21	    }
