    assertEquals(List.of("a,b"), one);
    assertEquals(List.of("a", "b"), two);
    // 指纹片段带逐项长度/名称前缀，也不会碰撞
    assertNotEquals(Allergens.fingerprintParts(one), Allergens.fingerprintParts(two));
}

